head.script:
// 전역 변수
scwin.currentMode = "new";
scwin.currentDefectId = "";

/**
 * 페이지 로드 시 초기화
 */
scwin.onpageload = function() {
    console.log("결함 팝업 로드 완료");
    scwin.initializeDefectData();
};

/**
 * 결함 팝업 표시 (외부에서 호출)
 */
scwin.showDefectPopup = function(mode, defectData) {
    console.log("결함 팝업 표시:", mode, defectData);

    scwin.currentMode = mode || "new";

    // 데이터 설정
    if (defectData && mode !== "new") {
        dmp_defDetail.setJSON(defectData);
        scwin.currentDefectId = defectData.id;
        scwin.loadDefFileList();
    } else {
        scwin.initializeDefectData();
    }

    // 모드에 따른 UI 설정
    scwin.setFormMode(scwin.currentMode);

    // 제목 설정
    var title = "";
    switch(mode) {
        case "new": title = "새 결함 등록"; break;
        case "edit": title = "결함 수정"; break;
        case "view": title = "결함 상세보기"; break;
        default: title = "결함 관리";
    }
    spn_popupTitle.setValue(title);

    console.log("결함 팝업 표시 완료");
};

/**
 * 결함 데이터 초기화
 */
scwin.initializeDefectData = function() {
    dmp_defDetail.setEmptyValue();

    // 기본값 설정
    dmp_defDetail.set("status", "대기");
    dmp_defDetail.set("priority", "보통");
    dmp_defDetail.set("isDeleted", "N");

    // 파일 관련 초기화
    dlt_defAttVoList.setJSON([]);

    console.log("결함 데이터 초기화 완료");
};

/**
 * 폼 모드 설정
 */
scwin.setFormMode = function(mode) {
    console.log("폼 모드 전환:", mode);

    if (mode === "edit" || mode === "new") {
        // 편집 모드
        scwin.setFieldsReadOnly(false);
        scwin.showFileUploadSection(true);

        // 버튼 상태 변경
        btn_save.show();
        btn_edit.hide();

        if (mode === "new") {
            btn_delete.hide();
        } else {
            btn_delete.show();
        }

    } else if (mode === "view") {
        // 조회 모드
        scwin.setFieldsReadOnly(true);
        scwin.showFileUploadSection(false);

        // 버튼 상태 변경
        btn_save.hide();
        btn_edit.show();
        btn_delete.show();
    }
};

/**
 * 필드 읽기 전용 설정
 */
scwin.setFieldsReadOnly = function(readOnly) {
    try {
        var editableFields = ["inp_name", "sel_priority", "sel_status", "cal_fixDueDate", "inp_assignee", "txa_description", "txa_remarks"];

        editableFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(readOnly);
            }
        });

    } catch(e) {
        console.error("필드 읽기 전용 설정 오류:", e);
    }
};

/**
 * 파일 업로드 섹션 표시
 */
scwin.showFileUploadSection = function(show) {
    try {
        if (show) {
            grp_fileUpload.show();
        } else {
            grp_fileUpload.hide();
        }
    } catch(e) {
        console.error("파일 업로드 섹션 표시 오류:", e);
    }
};

/**
 * 저장 버튼 클릭
 */
scwin.btn_save_onclick = function(e) {
    console.log("저장 버튼 클릭");

    // 유효성 검사
    if (!scwin.validateForm()) {
        return;
    }

    // 현재 시간 설정
    var currentTime = new Date().toISOString();

    if (scwin.currentMode === "new") {
        dmp_defDetail.set("createdAt", currentTime);
        dmp_defDetail.set("updatedAt", currentTime);
        $c.sbm.execute($p, sbm_insertDef);
    } else {
        dmp_defDetail.set("updatedAt", currentTime);
        $c.sbm.execute($p, sbm_updateDef);
    }
};

/**
 * 폼 유효성 검사
 */
scwin.validateForm = function() {
    var name = dmp_defDetail.get("name");
    var description = dmp_defDetail.get("description");

    if (!name || name.trim() === "") {
        $c.win.alert("결함명을 입력해주세요.");
        return false;
    }

    if (!description || description.trim() === "") {
        $c.win.alert("결함 설명을 입력해주세요.");
        return false;
    }

    return true;
};

/**
 * 등록 완료
 */
scwin.sbm_insertDef_submitdone = function(e) {
    console.log("결함 등록 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return;
    }

    $c.win.alert("등록되었습니다.");
    scwin.closeDefectPopup();
};

/**
 * 수정 완료
 */
scwin.sbm_updateDef_submitdone = function(e) {
    console.log("결함 수정 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return;
    }

    $c.win.alert("수정되었습니다.");
    scwin.setFormMode("view");
    scwin.loadDefFileList();
};

/**
 * 삭제 완료
 */
scwin.sbm_deleteDef_submitdone = function(e) {
    console.log("결함 삭제 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return;
    }

    $c.win.alert("삭제되었습니다.");
    scwin.closeDefectPopup();
};

/**
 * 수정 버튼 클릭
 */
scwin.btn_edit_onclick = function(e) {
    console.log("수정 버튼 클릭");
    scwin.setFormMode("edit");
};

/**
 * 삭제 버튼 클릭
 */
scwin.btn_delete_onclick = function(e) {
    console.log("삭제 버튼 클릭");

    var defId = dmp_defDetail.get("id");

    if (!defId) {
        $c.win.alert("삭제할 결함을 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("삭제하시겠습니까?\n관련된 파일도 함께 삭제됩니다.");
    promise.then(function(result) {
        if (result) {
            $c.sbm.execute($p, sbm_deleteDef);
        }
    });
};

/**
 * 초기화 버튼 클릭
 */
scwin.btn_reset_onclick = function(e) {
    console.log("초기화 버튼 클릭");
    scwin.initializeDefectData();
    scwin.setFormMode("new");
};

/**
 * 파일 목록 로드
 */
scwin.loadDefFileList = function() {
    console.log("파일 목록 로드 시작");

    var defId = dmp_defDetail.get("id");
    console.log("결함 ID:", defId);

    if (!defId || defId.trim() === "") {
        console.log("결함 ID가 없습니다. 파일 목록을 초기화합니다.");
        dlt_defAttVoList.setJSON([]);
        return;
    }

    $c.sbm.execute($p, sbm_selectDefFileList);
};

/**
 * 파일 목록 조회 완료
 */
scwin.sbm_selectDefFileList_submitdone = function(e) {
    console.log("파일 목록 조회 응답 처리 시작");

    try {
        var responseData = e.responseJSON;
        var elData = responseData ? responseData.elData : null;
        var elHeader = responseData ? responseData.elHeader : null;

        if (!elHeader || elHeader.resSuc !== true) {
            console.error("파일 목록 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
            dlt_defAttVoList.setJSON([]);
            return;
        }

        var fileList = [];
        if (elData && elData.attVoList) {
            fileList = elData.attVoList;
        }

        console.log("조회된 파일 개수:", fileList.length);
        dlt_defAttVoList.setJSON(fileList);

        console.log("파일 목록 조회 응답 처리 완료");

    } catch (error) {
        console.error("응답 처리 중 오류:", error);
        dlt_defAttVoList.setJSON([]);
    }
};

/**
 * 파일 목록 조회 실패 콜백
 */
scwin.sbm_selectDefFileList_submiterror = function(e) {
    console.error("파일 목록 조회 실패:", e);
    dlt_defAttVoList.setJSON([]);
};

/**
 * 파일 그리드 액션 버튼 클릭
 */
scwin.fileActionClick = function(row, col, colId, targetId) {
    console.log("파일 액션 클릭:", row, targetId);

    var rowData = dlt_defAttVoList.getRowJSON(row);
    var fileId = rowData.fileId;
    var fileName = rowData.originalFileName;

    if (!fileId) {
        alert("파일 ID가 없습니다.");
        return;
    }

    // 다운로드 또는 삭제 처리
    if (targetId && targetId.indexOf("download") >= 0) {
        scwin.downloadFile(fileId, fileName);
    } else if (targetId && targetId.indexOf("delete") >= 0) {
        scwin.deleteFile(fileId);
    } else {
        scwin.downloadFile(fileId, fileName);
    }
};

/**
 * 파일 다운로드
 */
scwin.downloadFile = function(fileId, fileName) {
    console.log("파일 다운로드:", fileName, "ID:", fileId);

    if (!fileId || !fileName) {
        alert("다운로드할 파일 정보가 없습니다.");
        return;
    }

    try {
        var downloadUrl = "/InsWebApp/FileDownload.pwkjson?fileId=" + encodeURIComponent(fileId);

        var iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        iframe.src = downloadUrl;

        document.body.appendChild(iframe);

        setTimeout(function() {
            if (iframe.parentNode) {
                document.body.removeChild(iframe);
            }
        }, 3000);

        console.log("파일 다운로드 요청 완료");

    } catch (error) {
        console.error("파일 다운로드 실패:", error);
        alert("파일 다운로드 중 오류가 발생했습니다: " + error.message);
    }
};

/**
 * 파일 삭제
 */
scwin.deleteFile = function(fileId) {
    console.log("파일 삭제:", fileId);

    if (!fileId) {
        alert("삭제할 파일을 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            scwin.currentFileId = fileId;
            $c.sbm.execute($p, sbm_deleteDefFile);
        }
    });
};

scwin.sbm_deleteDefFile_submit = function(e) {
    var fileId = scwin.currentFileId;
    if (!fileId) {
        console.error("삭제할 파일 ID가 없습니다.");
        return;
    }

    var deleteUrl = "/InsWebApp/DEFFileDelete.pwkjson?fileId=" + encodeURIComponent(fileId);
    sbm_deleteDefFile.setAction(deleteUrl);
    sbm_deleteDefFile.setRequestData("");
};

/**
 * 파일 삭제 완료
 */
scwin.sbm_deleteDefFile_submitdone = function(e) {
    console.log("파일 삭제 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        alert("파일 삭제 실패: " + (elHeader ? elHeader.resMsg : "알 수 없는 오류"));
        return;
    }

    alert("파일이 삭제되었습니다.");
    scwin.loadDefFileList();
};

/**
 * 팝업 닫기
 */
scwin.closeDefectPopup = function() {
    console.log("결함 팝업 닫기");

    // 부모 창의 새로고침 함수 호출 (있다면)
    if (typeof window.opener !== 'undefined' && window.opener && window.opener.scwin && typeof window.opener.scwin.refreshDefectList === 'function') {
        window.opener.scwin.refreshDefectList();
    }

    window.close();
};

/**
 * 팝업 닫기 버튼
 */
scwin.btn_close_onclick = function(e) {
    console.log("팝업 닫기 버튼 클릭");
    scwin.closeDefectPopup();
};

/**
 * 현재 미리보기 파일 다운로드
 */
scwin.downloadCurrentFile = function() {
    var fileId = dmp_currentFile.get("fileId");
    var fileName = dmp_currentFile.get("originalFileName");

    if (fileId && fileName) {
        scwin.downloadFile(fileId, fileName);
    } else {
        alert("다운로드할 파일 정보가 없습니다.");
    }
};

/**
 * 현재 사용자명 가져오기
 */
scwin.getCurrentUserName = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow && headerFrame.getWindow().scwin) {
                return headerFrame.getWindow().scwin.USER_NAME || "현재 사용자";
            }
        }
        return "현재 사용자";
    } catch (e) {
        console.error("사용자명 가져오기 실패:", e);
        return "현재 사용자";
    }
};

/**
 * 결함 상태가 '완료'로 변경될 때 관련 테스트 상태 업데이트
 */
scwin.handleDefectStatusChange = function(newStatus) {
    if (newStatus === "완료") {
        var testId = dmp_defDetail.get("testId");
        if (testId) {
            // 관련된 단위테스트를 성공으로 변경하는 API 호출
            scwin.updateRelatedTestStatus(testId, "SUC");
        }
    }
};

/**
 * 관련 테스트 상태 업데이트
 */
scwin.updateRelatedTestStatus = function(testId, newStatus) {
    console.log("관련 테스트 상태 업데이트:", testId, newStatus);

    try {
        // Ajax 호출로 테스트 상태 업데이트
        fetch("/InsWebApp/UNIT001UpdateResult.pwkjson", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                unitTestVo: {
                    testCaseId: testId,
                    testStatus: newStatus,
                    updatedAt: new Date().toISOString()
                }
            })
        })
        .then(function(response) { return response.json(); })
        .then(function(data) {
            if (data.elHeader && data.elHeader.resSuc) {
                console.log("관련 테스트 상태 업데이트 완료");
            } else {
                console.warn("테스트 상태 업데이트 실패:", data.elHeader ? data.elHeader.resMsg : "알 수 없는 오류");
            }
        })
        .catch(function(error) {
            console.error("테스트 상태 업데이트 오류:", error);
        });
    } catch (e) {
        console.error("테스트 상태 업데이트 실패:", e);
    }
};
